# test_flatten_dict.py
import pytest

# Replace "your_module" with the actual module name where flatten_dict is defined.
from your_module import flatten_dict


def test_flatten_dict_flat_dictionary():
    data = {
        "a": 1,
        "b": 2,
        "c": 3,
    }

    assert flatten_dict(data) == {
        "a": 1,
        "b": 2,
        "c": 3,
    }


def test_flatten_dict_nested_dictionary():
    data = {
        "a": {
            "b": {
                "c": 1,
            },
            "d": 2,
        },
        "e": 3,
    }

    assert flatten_dict(data) == {
        "a.b.c": 1,
        "a.d": 2,
        "e": 3,
    }


def test_flatten_dict_with_custom_separator():
    data = {
        "a": {
            "b": {
                "c": 1,
            },
        },
    }

    assert flatten_dict(data, sep="_") == {
        "a_b_c": 1,
    }


def test_flatten_dict_with_parent_key():
    data = {
        "a": 1,
        "b": {
            "c": 2,
        },
    }

    assert flatten_dict(data, parent_key="root") == {
        "root.a": 1,
        "root.b.c": 2,
    }


def test_flatten_dict_empty_dictionary():
    assert flatten_dict({}) == {}


def test_flatten_dict_nested_empty_dictionary_is_omitted():
    data = {
        "a": {},
        "b": 1,
    }

    assert flatten_dict(data) == {
        "b": 1,
    }


def test_flatten_dict_deeply_nested_empty_dictionary_returns_empty_dict():
    data = {
        "a": {
            "b": {
                "c": {},
            },
        },
    }

    assert flatten_dict(data) == {}


def test_flatten_dict_preserves_non_dict_values():
    data = {
        "a": None,
        "b": [1, 2, 3],
        "c": (4, 5),
        "d": True,
        "e": {
            "f": "hello",
        },
    }

    assert flatten_dict(data) == {
        "a": None,
        "b": [1, 2, 3],
        "c": (4, 5),
        "d": True,
        "e.f": "hello",
    }


def test_flatten_dict_does_not_mutate_original_dictionary():
    data = {
        "a": {
            "b": 1,
        },
    }
    original = {
        "a": {
            "b": 1,
        },
    }

    result = flatten_dict(data)

    assert result == {"a.b": 1}
    assert data == original


def test_flatten_dict_key_collision_last_value_wins():
    data = {
        "a": {
            "b": 1,
        },
        "a.b": 2,
    }

    assert flatten_dict(data) == {
        "a.b": 2,
    }


def test_flatten_dict_existing_separator_in_key_is_not_escaped():
    data = {
        "a.b": {
            "c": 1,
        },
    }

    assert flatten_dict(data) == {
        "a.b.c": 1,
    }


def test_flatten_dict_with_non_string_top_level_keys():
    data = {
        1: "one",
        2: {
            "a": "two-a",
        },
    }

    assert flatten_dict(data) == {
        1: "one",
        "2.a": "two-a",
    }


